def patch(fp):
    with open(fp, "r", encoding="utf-8") as f:
        d = json.load(f)
    for cat in d["categories"]:
        if cat.get("id") == "xray_scan":
            for sub in cat["subcategories"]:
                if sub["id"] == "medical_anatomy_male":
                    for t in sub["templates"]:
                        if t["id"] == "med_male_specific":
                            for old, new in MALE_BILINGUAL.items():
                                if old in t["prompt"]:
                                    t["prompt"] = t["prompt"].replace(old, new, 1)
                            print(f"  patched male_specific in {fp}")
                if sub["id"] == "medical_anatomy_female":
                    for t in sub["templates"]:
                        if t["id"] == "med_female_specific":
                            for old, new in FEMALE_BILINGUAL.items():
                                if old in t["prompt"]:
                                    t["prompt"] = t["prompt"].replace(old, new, 1)
                            print(f"  patched female_specific in {fp}")
    with open(fp, "w", encoding="utf-8") as f:
        json.dump(d, f, ensure_ascii=False, indent=2)
    print("saved", fp)


